import {LESSONS, AREAS, FLASHCARDS, ESSAY_TOPICS, EXAM_DATES, OFFICIAL_LINKS} from './data.js';
import {store} from './store.js';

const $ = s => document.querySelector(s);
const main = $('#main');
const icons = {
  home: '<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
  book: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
  calendar: '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
  target: '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  pen: '<path d="M12 20h9"/><path d="m16 5 3 3-11 11H5v-3z"/><path d="m14 7 3 3"/>',
  layers: '<path d="m12 3-9 5 9 5 9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',
  chart: '<path d="M3 3v18h18M7 16v-4M12 16V8M17 16V5"/>',
  settings: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l-1.78 1.78a1.7 1.7 0 0 0-1.88-.34l-1.42.59a1.7 1.7 0 0 0-1.05 1.57H11a1.7 1.7 0 0 0-1.05-1.57l-1.42-.59a1.7 1.7 0 0 0-1.88.34l-1.78-1.78A1.7 1.7 0 0 0 5.2 15l-.59-1.42A1.7 1.7 0 0 0 3 12.53v-1.06a1.7 1.7 0 0 0 1.61-1.05L5.2 9a1.7 1.7 0 0 0-.34-1.88l1.78-1.78A1.7 1.7 0 0 0 8.53 5l1.42-.59A1.7 1.7 0 0 0 11 2.8h2a1.7 1.7 0 0 0 1.05 1.61l1.42.59a1.7 1.7 0 0 0 1.88.34l1.78 1.78A1.7 1.7 0 0 0 18.8 9l.59 1.42A1.7 1.7 0 0 0 21 11.47v1.06a1.7 1.7 0 0 0-1.61 1.05z"/>',
  user: '<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
  menu: '<path d="M4 7h16M4 12h16M4 17h16"/>',
  close: '<path d="M5 5l14 14M19 5 5 19"/>',
  arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>',
  arrowleft: '<path d="M19 12H5m6-6-6 6 6 6"/>',
  check: '<path d="M5 12l4 4L19 6"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  spark: '<path d="m12 2 2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4z"/>',
  lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
  download: '<path d="M12 3v12m-4-4 4 4 4-4M4 17v3h16v-3"/>',
  upload: '<path d="M12 20V8m-4 4 4-4 4 4M4 7V4h16v3"/>',
  moon: '<path d="M20 15a8 8 0 0 1-11-11 8 8 0 1 0 11 11z"/>',
  sun: '<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  search: '<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
  flag: '<path d="M5 21V4m0 0c5-4 8 4 15 0v11c-7 4-10-4-15 0"/>',
  refresh: '<path d="M20 11a8 8 0 1 0-2 6M20 4v7h-7"/>',
  play: '<path d="m8 5 11 7-11 7z"/>',
  pause: '<path d="M8 5v14M16 5v14"/>',
  heart: '<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>'
};
function icon(name) {return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${icons[name] || icons.spark}</svg>`}
function hydrateIcons(root = document) {root.querySelectorAll('[data-icon]').forEach(n => {n.innerHTML = icon(n.dataset.icon); n.removeAttribute('data-icon')})}
function esc(x) {return String(x ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]))}
function normalize(str) {return String(str).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()}
function firstName() {return (store.state.profile.name.trim().split(' ')[0] || 'Estudante')}
const fmt = new Intl.DateTimeFormat('pt-BR', {day: '2-digit', month: 'long', year: 'numeric'});
function isoToday() {const parts = new Intl.DateTimeFormat('en-US', {timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit'}).formatToParts(new Date()); const p = Object.fromEntries(parts.map(x => [x.type, x.value])); return `${p.year}-${p.month}-${p.day}`}
function daysUntil(date) {const a = new Date(`${isoToday()}T00:00:00Z`).getTime(), b = new Date(`${date}T00:00:00Z`).getTime(); return Math.round((b - a) / 86400000)}
function formatDay(iso) {return fmt.format(new Date(`${iso}T12:00:00-03:00`))}
function percent(a, b) {return b ? Math.round(a / b * 100) : 0}
function done(id) {return store.state.lessonDone.includes(id)}
function answeredCount() {return Object.keys(store.state.answers).length}
function questionList() {return LESSONS.flatMap(l => l.questions.map((q, i) => ({...q, key: `${l.id}:${i}`, area: l.area, lessonId: l.id, lessonTitle: l.title})))}
function areaStats(area) {const lessons = LESSONS.filter(l => l.area === area), questions = questionList().filter(q => q.area === area), responses = questions.map(q => store.state.answers[q.key]).filter(Boolean), correct = responses.filter(a => a.correct).length; return {finished: lessons.filter(l => done(l.id)).length, total: lessons.length, answered: responses.length, correct, accuracy: percent(correct, responses.length)}}
function progress() {return percent(LESSONS.filter(l => done(l.id)).length, LESSONS.length)}
function totalAccuracy() {const a = Object.values(store.state.answers); return percent(a.filter(x => x.correct).length, a.length)}
function button(href, title, variant = 'secondary', i = 'arrow') {return `<a class="button button-${variant}" href="${href}">${esc(title)} ${icon(i)}</a>`}
function lessonCard(l) {return `<a class="card lesson-card" href="#/aula/${l.id}" data-lesson-card data-search="${esc(normalize(`${l.title} ${l.summary} ${AREAS[l.area].name}`))}" data-area="${l.area}"><div class="lesson-top"><span class="lesson-symbol" aria-hidden="true">${AREAS[l.area].icon}</span><span class="pill ${done(l.id) ? 'pill-mint' : 'pill-accent'}">${done(l.id) ? '✓ Concluída' : esc(l.level)}</span></div><div><span class="tiny subtle">${AREAS[l.area].name} · ${l.minutes} min</span><h3>${esc(l.title)}</h3></div><p>${esc(l.summary)}</p><div class="lesson-bottom"><span>${l.questions.length} exercícios comentados</span><span>${done(l.id) ? 'Revisar' : 'Começar'} ${icon('arrow')}</span></div></a>`}
function pageHead(kicker, title, subtitle, actions = '') {return `<header class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${actions}</header>`}
function sectionHead(title, subtitle = '', link = '', label = 'Ver todos') {return `<div class="section-head"><div><h2>${esc(title)}</h2>${subtitle ? `<p>${esc(subtitle)}</p>` : ''}</div>${link ? `<a class="text-link" href="${link}">${esc(label)} ${icon('arrow')}</a>` : ''}</div>`}
function metric(iconName, value, label, foot = '') {return `<article class="card metric"><span class="metric-icon">${icon(iconName)}</span><span class="metric-value">${esc(value)}</span><span class="metric-label">${esc(label)}</span>${foot ? `<span class="metric-foot">${esc(foot)}</span>` : ''}</article>`}
function countdownCard() {const left1 = daysUntil(EXAM_DATES[0].date), left2 = daysUntil(EXAM_DATES[1].date); return `<div class="card countdown-card"><span class="eyebrow">CONTAGEM REGRESSIVA</span><div class="countdown-number">${left1 > 0 ? left1 + ' dias' : left1 === 0 ? 'É hoje!' : 'Concluído'}</div><div class="countdown-date">1º dia · 8 de novembro de 2026</div><div class="countdown-sub">Linguagens, Humanas e Redação</div><div class="countdown-separator"></div><div class="spaced"><span class="small muted">2º dia · 15 de novembro</span><strong>${left2 > 0 ? `${left2} dias` : left2 === 0 ? 'Hoje' : 'Concluído'}</strong></div><p class="tiny subtle" style="margin:12px 0 0">Datas oficiais, considerando o calendário de Brasília.</p></div>`}
function createPlan(date) {
  const phase = date > EXAM_DATES[0].date ? 'second' : 'first';
  const subjects = phase === 'first' ? ['linguagens', 'humanas', 'matematica', 'natureza'] : ['matematica', 'natureza'];
  const difficult = [...subjects].sort((a, b) => {const sa = areaStats(a), sb = areaStats(b); return (sa.answered ? sa.accuracy : 80) - (sb.answered ? sb.accuracy : 80)});
  const dayIndex = Math.abs(Math.floor((Date.parse(date + 'T00:00:00Z') - Date.parse('2026-10-22T00:00:00Z')) / 86400000));
  const area = difficult[dayIndex % difficult.length];
  const choices = LESSONS.filter(l => l.area === area); const lesson = choices.find(l => !done(l.id)) || choices[dayIndex % choices.length];
  const second = LESSONS.filter(l => l.area === subjects[(dayIndex + 1) % subjects.length]).find(l => !done(l.id));
  const tasks = [{id: 'aula', title: `Estudar: ${lesson.title}`, details: `${lesson.minutes} min · ${AREAS[area].name}`, href: `#/aula/${lesson.id}`, icon: 'book'}];
  if (second && second.id !== lesson.id && store.state.profile.goalMinutes >= 75) tasks.push({id: 'extra', title: `Revisão: ${second.title}`, details: `${second.minutes} min · outro assunto`, href: `#/aula/${second.id}`, icon: 'book'});
  tasks.push({id: 'questoes', title: 'Resolver um treino de questões', details: '10–20 min · praticar e conferir erros', href: '#/questoes', icon: 'target'});
  tasks.push(phase === 'first' ? {id: 'redacao', title: 'Treinar redação ou repertório', details: '15–30 min · organização de argumentos', href: '#/redacao', icon: 'pen'} : {id: 'flashcards', title: 'Revisar conceitos essenciais', details: '10 min · treino de memória', href: '#/flashcards', icon: 'layers'});
  return tasks;
}
function getPlan(date = isoToday()) {if (!store.state.planDays || typeof store.state.planDays !== 'object') store.state.planDays = {}; if (!store.state.planDays[date]) {const items = createPlan(date); store.update(s => {s.planDays = s.planDays || {}; s.planDays[date] = items;}); return items;} return store.state.planDays[date]}
function localHref(href) {return typeof href === 'string' && /^#\/(inicio|biblioteca|aula\/[a-z0-9-]+|plano|questoes|redacao|flashcards|desempenho|configuracoes)$/.test(href) ? href : '#/inicio'}
function taskList(tasks, date) {return `<div class="activity-list">${tasks.map(t => {const checked = Boolean(store.state.planChecked[`${date}:${t.id}`]); return `<div class="activity ${checked ? 'done' : ''}"><span class="activity-icon">${icon(t.icon)}</span><div class="activity-main"><strong>${esc(t.title)}</strong><span>${esc(t.details)}</span><div><a class="text-link" href="${localHref(t.href)}">${esc(checked ? 'Rever' : 'Acessar')} ${icon('arrow')}</a></div></div><button type="button" class="check-control ${checked ? 'checked' : ''}" data-action="check-plan" data-date="${date}" data-task="${esc(t.id)}" aria-pressed="${checked}" aria-label="${checked ? 'Desmarcar' : 'Concluir'}: ${esc(t.title)}">${icon('check')}</button></div>`}).join('')}</div>`}
function renderHome() {const date = isoToday(), tasks = getPlan(date), num = tasks.filter(t => store.state.planChecked[`${date}:${t.id}`]).length, next = LESSONS.filter(l => !done(l.id)).slice(0, 3); return `<section class="hero"><div class="hero-content"><div class="eyebrow">✦ SEU PRÓXIMO CAPÍTULO COMEÇA AQUI</div><h1>Seu futuro se constrói <em>um dia de cada vez.</em></h1><p>Olá, ${esc(firstName())}! Você não precisa dominar tudo hoje. Escolha um passo, aprenda com calma e continue avançando.</p><div class="hero-actions">${button('#/plano', 'Meu plano de hoje', 'primary')}${button('#/biblioteca', 'Explorar matérias', 'ghost-light', 'book')}</div></div><div class="hero-illustration" aria-hidden="true"><div class="sunburst">✳</div></div></section><section class="grid-4" aria-label="Visão geral do seu progresso">${metric('calendar', Math.max(0, daysUntil(EXAM_DATES[0].date)), 'Dias até a 1ª prova', daysUntil(EXAM_DATES[0].date) < 0 ? 'Prova já realizada' : '8 de novembro de 2026')}${metric('book', `${progress()}%`, 'Biblioteca concluída', `${store.state.lessonDone.length} de ${LESSONS.length} capítulos`)}${metric('target', `${totalAccuracy()}%`, 'Acerto nos exercícios', `${answeredCount()} respostas registradas`)}${metric('check', `${num}/${tasks.length}`, 'Tarefas do dia', 'Pequenos passos contam')}</section><section class="grid-2 gap-section"><div class="card"><div class="section-head"><div><h2>Seu plano para hoje</h2><p>${formatDay(date)} · feito no seu ritmo</p></div><a class="text-link" href="#/plano">Abrir plano ${icon('arrow')}</a></div><div class="progress-line"><span>Atividades concluídas</span><strong>${num}/${tasks.length}</strong></div><div class="progress" role="progressbar" aria-label="Atividades do dia concluídas" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent(num, tasks.length)}"><span style="width:${percent(num, tasks.length)}%"></span></div><div style="margin-top:20px">${taskList(tasks, date)}</div></div>${countdownCard()}</section><section class="gap-section">${sectionHead('Continue aprendendo', 'Capítulos selecionados para começar sua jornada', '#/biblioteca', 'Toda a biblioteca')}<div class="grid-3">${(next.length ? next : LESSONS.slice(0, 3)).map(lessonCard).join('')}</div></section><section class="card gap-section"><div class="spaced"><div><span class="eyebrow">LEMBRETE</span><h3 style="margin:7px 0">Progresso real é progresso possível.</h3><p class="small" style="margin:0">Faça pausas, reveja o que errou e comemore cada conquista.</p></div>${button('#/flashcards', 'Revisar flashcards', 'secondary', 'layers')}</div></section>`}
function renderLibrary() {return `${pageHead('APRENDIZADO', 'Sua biblioteca', 'Capítulos organizados por área, com explicações, exemplos e exercícios comentados.')}<label for="lesson-search" class="sr-only">Pesquisar conteúdos</label><div class="search-field">${icon('search')}<input type="search" id="lesson-search" placeholder="Pesquisar por tema ou matéria..." value="${esc(librarySearch)}" autocomplete="off"></div><div class="filters" role="group" aria-label="Filtrar matérias">${[['all', 'Todas as áreas'], ...Object.entries(AREAS).map(([k, v]) => [k, v.name])].map(([k, name]) => `<button class="filter-button ${libraryFilter === k ? 'active' : ''}" data-action="filter" data-filter="${k}" aria-pressed="${libraryFilter === k}">${esc(name)}</button>`).join('')}</div><div class="grid-3" id="lesson-grid">${LESSONS.map(lessonCard).join('')}</div><div class="empty-state" id="lesson-empty" hidden>Nenhum capítulo encontrado para esta busca.</div><div class="note gap-section">${icon('book')} <strong>Sobre a biblioteca:</strong> estes ${LESSONS.length} capítulos formam um núcleo inicial de estudos, não o programa integral do ENEM. Veja a <a class="text-link" target="_blank" rel="noopener noreferrer" href="${OFFICIAL_LINKS.matrix}">Matriz oficial ${icon('arrow')}</a>.</div>`}
function renderLesson(l) {const answers = l.questions.map((q, i) => ({q, i, result: store.state.answers[`${l.id}:${i}`]})); return `<div class="details-header"><a href="#/biblioteca" class="text-link">${icon('arrowleft')} Voltar à biblioteca</a></div><header class="details-hero"><span class="pill pill-accent">${esc(AREAS[l.area].name)} · ${esc(l.level)}</span><h1>${esc(l.title)}</h1><p>${esc(l.summary)}</p><div class="row-actions"><span class="pill">${icon('clock')} ${l.minutes} minutos estimados</span><span class="pill">${icon('target')} ${l.questions.length} exercícios</span>${done(l.id) ? '<span class="pill pill-mint">✓ Concluído</span>' : ''}</div></header><div class="detail-body"><article class="card prose"><h2>O que você vai aprender</h2><ul>${l.objectives.map(x => `<li>${esc(x)}</li>`).join('')}</ul><div class="divider"></div>${l.sections.map((s, i) => `<section><div class="eyebrow">PARTE ${i + 1}</div><h2>${esc(s.title)}</h2>${s.paragraphs.map(p => `<p>${esc(p)}</p>`).join('')}${s.example ? `<div class="example"><strong>Exemplo prático</strong><div>${esc(s.example)}</div></div>` : ''}${s.bullets ? `<ul>${s.bullets.map(b => `<li>${esc(b)}</li>`).join('')}</ul>` : ''}</section><div class="divider"></div>`).join('')}<h2>Hora de praticar</h2><p>Responda e veja a explicação comentada. Seu resultado fica salvo na sua conta.</p>${answers.map(({q, i, result}) => `<section class="question"><div class="question-head"><span class="pill">Questão ${i + 1} de ${l.questions.length}</span>${result ? `<span class="pill ${result.correct ? 'pill-mint' : 'pill-rose'}">${result.correct ? 'Acertou' : 'Revisar'}</span>` : ''}</div><div class="question-title">${esc(q.prompt)}</div><div class="option-list">${q.options.map((o, n) => `<button type="button" ${result ? 'disabled' : ''} class="option-button ${result && n === q.answer ? 'correct' : ''} ${result && n === result.selected && !result.correct ? 'wrong' : ''}" data-action="answer" data-lesson="${l.id}" data-index="${i}" data-choice="${n}"><span class="option-letter">${'ABCD'[n]}</span>${esc(o)}</button>`).join('')}</div>${result ? `<div class="answer-feedback"><strong>${result.correct ? 'Muito bem!' : 'Vamos entender essa questão.'}</strong><p>${esc(q.explanation)}</p></div>` : ''}</section>`).join('')}<div class="row-actions"><button type="button" class="button button-primary" data-action="finish-lesson" data-lesson="${l.id}">${icon('check')} ${done(l.id) ? 'Marcar como não concluída' : 'Concluir capítulo'}</button><button type="button" class="button button-secondary" data-action="retry-lesson" data-lesson="${l.id}">${icon('refresh')} Refazer exercícios</button></div></article><aside class="card sticky-panel"><div class="eyebrow">SEU CAMINHO</div><h3 style="margin-top:7px">Cada capítulo conta</h3><div class="progress-line"><span>Seu progresso geral</span><strong>${progress()}%</strong></div><div class="progress"><span style="width:${progress()}%"></span></div><div class="divider"></div><p class="small">Esta aula ajuda a construir a base. Se algo ficou difícil, releia a explicação antes de tentar de novo.</p>${button('#/biblioteca', 'Ver outras aulas', 'secondary', 'book')}</aside></div>`}
function renderPlan() {const date = isoToday(), tasks = getPlan(date), complete = tasks.filter(t => store.state.planChecked[`${date}:${t.id}`]).length; const weekly = Array.from({length: 7}, (_, i) => {const today = new Date(`${date}T12:00:00Z`); today.setUTCDate(today.getUTCDate() + i); return today.toISOString().slice(0, 10)}); return `${pageHead('ORGANIZAÇÃO', 'Meu plano de estudos', 'Um roteiro enxuto para estudar com foco, sem tentar aprender o ensino médio inteiro de uma vez.')}<div class="grid-2"><div class="card"><div class="eyebrow">SUA META DE HOJE</div><h2 style="margin:7px 0 3px">${complete === tasks.length ? 'Excelente! Plano concluído.' : `${tasks.length - complete} atividades pela frente`}</h2><p class="small">${formatDay(date)} · meta pessoal: ${store.state.profile.goalMinutes} min/dia</p><div class="progress-line"><span>Concluído</span><strong>${percent(complete, tasks.length)}%</strong></div><div class="progress" role="progressbar" aria-label="Plano diário concluído" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent(complete, tasks.length)}"><span style="width:${percent(complete, tasks.length)}%"></span></div><div style="margin-top:22px">${taskList(tasks, date)}</div></div>${countdownCard()}</div><div class="gap-section">${sectionHead('Próximos sete dias', 'Uma prévia flexível; você pode adaptar sua meta em Configurações.')}<div class="grid-3">${weekly.map((d, i) => {const plan = i === 0 ? tasks : (store.state.planDays?.[d] || createPlan(d)); const doneTasks = plan.filter(t => store.state.planChecked[`${d}:${t.id}`]).length; return `<article class="card tight"><div class="spaced"><span class="pill ${i === 0 ? 'pill-accent' : ''}">${i === 0 ? 'HOJE' : new Intl.DateTimeFormat('pt-BR', {weekday: 'short', timeZone: 'UTC'}).format(new Date(`${d}T12:00:00Z`))}</span><span class="tiny subtle">${d.slice(8, 10)}/${d.slice(5, 7)}</span></div><h3 style="margin:15px 0 8px">${esc(plan[0]?.title || 'Revisão')}</h3><p class="small">${plan.length} etapas planejadas · ${doneTasks} concluídas</p><div class="progress"><span style="width:${percent(doneTasks, plan.length)}%"></span></div></article>`}).join('')}</div></div><div class="note gap-section"><strong>Como o plano é montado:</strong> ele considera a fase da prova, os resultados dos exercícios e os capítulos que faltam. O roteiro do dia é salvo ao ser gerado para não mudar enquanto você estuda. Conteúdos do segundo dia recebem mais atenção depois de 8/11.</div>`}
function renderQuestions() {const attempts = store.state.quizAttempts; const last = attempts.at(-1); if (quizSession) return renderOngoingQuiz(); if (quizResult) return renderQuizResult(); return `${pageHead('PRÁTICA', 'Questões e simulados', 'Treine o raciocínio, acompanhe seu desempenho e aprenda com resoluções comentadas.')}<div class="grid-2"><button class="choice-card" data-action="start-quiz" data-mode="practice"><span class="lesson-symbol" aria-hidden="true">◎</span><strong>Treino rápido</strong><span>8 questões variadas, sem limite de tempo. Feedback e comentários ao final.</span><span class="text-link">Começar treino ${icon('arrow')}</span></button><button class="choice-card" data-action="start-quiz" data-mode="timed"><span class="lesson-symbol" aria-hidden="true">◷</span><strong>Mini-simulado</strong><span>12 questões autorais, com limite de 20 minutos. Não reproduz uma prova oficial.</span><span class="text-link">Iniciar simulado ${icon('arrow')}</span></button></div><section class="grid-3 gap-section">${metric('target', String(attempts.length), 'Treinos realizados')}${metric('chart', last ? `${last.score}/${last.total}` : '—', 'Resultado do último treino')}${metric('clock', last ? new Date(last.completedAt).toLocaleDateString('pt-BR') : '—', 'Última prática')}</section><section class="card gap-section">${sectionHead('Histórico de treinos', 'Seus últimos cinco resultados')}${attempts.length ? `<div class="activity-list">${[...attempts].reverse().slice(0, 5).map(t => `<div class="activity"><span class="activity-icon">${icon('target')}</span><div class="activity-main"><strong>${t.mode === 'timed' ? 'Mini-simulado' : 'Treino rápido'}</strong><span>${new Date(t.completedAt).toLocaleDateString('pt-BR')} · ${t.total} questões</span></div><strong>${t.score}/${t.total}</strong></div>`).join('')}</div>` : `<div class="empty-state">${icon('target')}<strong>Seu primeiro treino começa aqui.</strong><span>Os resultados aparecerão depois que você resolver um conjunto de questões.</span></div>`}</section>`}
function renderOngoingQuiz() {const s = quizSession, q = s.list[s.index], selected = s.responses[s.index]; return `<div class="details-header"><button type="button" class="text-button" data-action="leave-quiz">${icon('arrowleft')} Encerrar este treino</button></div><div class="card"><div class="quiz-meta"><div><span class="eyebrow">${s.mode === 'timed' ? 'MINI-SIMULADO' : 'TREINO RÁPIDO'}</span><h2 style="margin:7px 0">Questão ${s.index + 1} de ${s.list.length}</h2></div>${s.mode === 'timed' ? `<span class="pill pill-gold">${icon('clock')} <span id="quiz-clock">20:00</span></span>` : '<span class="pill">Sem cronômetro</span>'}</div><div class="progress" aria-label="Progresso do treino"><span style="width:${percent(s.index, s.list.length)}%"></span></div><div class="divider"></div><span class="pill">${esc(AREAS[q.area].name)}</span><h3 style="font-size:clamp(1.15rem,2.5vw,1.4rem);margin:18px 0 24px;line-height:1.6">${esc(q.prompt)}</h3><div class="option-list">${q.options.map((option, i) => `<button class="option-button ${selected === i ? 'correct' : ''}" data-action="quiz-answer" data-choice="${i}" aria-pressed="${selected === i}"><span class="option-letter">${'ABCD'[i]}</span>${esc(option)}</button>`).join('')}</div><div class="spaced" style="margin-top:24px"><span class="small muted">Selecione uma alternativa para continuar.</span><button type="button" class="button button-primary" data-action="quiz-next" ${selected === undefined ? 'disabled' : ''}>${s.index === s.list.length - 1 ? 'Finalizar treino' : 'Próxima questão'} ${icon('arrow')}</button></div></div>`}
function renderQuizResult() {const r = quizResult; return `${pageHead('RESULTADO', 'Seu treino terminou', 'Veja seus acertos e entenda as resoluções antes de tentar outra vez.')}<div class="grid-3">${metric('target', `${r.score}/${r.total}`, 'Questões corretas')}${metric('chart', `${percent(r.score, r.total)}%`, 'Aproveitamento')}${metric('clock', `${Math.ceil(r.elapsedSec / 60)} min`, 'Tempo aproximado')}</div><section class="card gap-section"><div class="section-head"><h2>Correção comentada</h2><button class="button button-secondary button-small" type="button" data-action="back-quiz">Voltar aos treinos ${icon('arrow')}</button></div>${r.items.map((item, i) => `<div class="question"><div class="question-head"><span class="pill">Questão ${i + 1} · ${esc(AREAS[item.area].name)}</span><span class="pill ${item.chosen === item.answer ? 'pill-mint' : 'pill-rose'}">${item.chosen === item.answer ? 'Acertou' : 'Errou'}</span></div><strong class="question-title">${esc(item.prompt)}</strong><p class="small">Sua resposta: ${item.chosen === null ? 'Sem resposta' : esc(item.options[item.chosen])}</p><p class="small"><strong>Resposta correta:</strong> ${esc(item.options[item.answer])}</p><div class="answer-feedback"><p>${esc(item.explanation)}</p></div></div>`).join('')}</section>`}
function renderEssay() {const topic = ESSAY_TOPICS.find(t => t.id === essayTopic) || ESSAY_TOPICS[0], draft = store.state.essayDrafts[topic.id] || '', saved = store.state.essaySubmitted[topic.id], words = draft.trim() ? draft.trim().split(/\s+/).length : 0; return `${pageHead('ESCRITA', 'Laboratório de redação', 'Planeje, escreva e revise um texto dissertativo-argumentativo no seu ritmo.')}<div class="grid-2"><div class="stack"><section class="card"><div class="eyebrow">PROPOSTA DE REDAÇÃO • TREINO AUTORAL</div><div class="field" style="margin:15px 0"><label for="essay-topic">Escolha um tema para praticar</label><select id="essay-topic">${ESSAY_TOPICS.map(t => `<option value="${t.id}" ${t.id === topic.id ? 'selected' : ''}>${esc(t.title)}</option>`).join('')}</select></div><h2>${esc(topic.title)}</h2><p>${esc(topic.guide)}</p><span class="pill pill-accent">${esc(topic.axis)}</span><div class="divider"></div><h3>Como organizar o texto</h3><ol class="small muted" style="padding-left:20px"><li>Introdução: contextualize o tema e apresente a tese.</li><li>Desenvolvimento 1: formule um argumento com explicação e evidência.</li><li>Desenvolvimento 2: aprofunde outra causa ou consequência.</li><li>Conclusão: construa uma proposta de intervenção detalhada.</li></ol></section><div class="note warning"><strong>Atenção:</strong> este editor não corrige redações automaticamente e não atribui nota ENEM. A avaliação oficial segue cinco competências; consulte a <a class="text-link" href="${OFFICIAL_LINKS.essay}" target="_blank" rel="noopener noreferrer">cartilha do Inep ${icon('arrow')}</a>.</div></div><section class="card"><div class="spaced" style="margin-bottom:12px"><h2 style="margin:0">Seu texto</h2><span class="pill" id="essay-status">${saved ? 'Última versão finalizada salva' : 'Rascunho salvo automaticamente'}</span></div><label class="sr-only" for="essay-editor">Digite sua redação</label><textarea id="essay-editor" class="essay-editor" placeholder="Comece com sua introdução..." spellcheck="true">${esc(draft)}</textarea><div class="spaced" style="margin:13px 0 19px"><span class="small muted"><span id="essay-word-count">${words}</span> palavras · <span id="essay-char-count">${draft.length}</span> caracteres</span><span class="tiny subtle">Contagem de linhas não disponível no editor</span></div><h3>Checklist antes de finalizar</h3><div class="checklist">${['Apresentei uma tese clara.', 'Desenvolvi argumentos relacionados ao tema.', 'Utilizei repertório pertinente, sem inventar dados.', 'Conectei ideias com coesão.', 'Apresentei proposta de intervenção com agente, ação, meio, finalidade e detalhamento.'].map((c, i) => `<label><input type="checkbox" data-action="essay-check" data-check="${i}" ${store.state.essayChecklist?.[topic.id]?.[i] ? 'checked' : ''}>${esc(c)}</label>`).join('')}</div><div class="row-actions" style="margin-top:20px"><button type="button" class="button button-primary" data-action="submit-essay">${icon('check')} Salvar versão finalizada</button><button type="button" class="button button-secondary" data-action="copy-essay">Copiar texto</button></div>${saved ? `<p class="small muted" style="margin-top:10px">Última finalização: ${new Date(saved.savedAt).toLocaleString('pt-BR')}. Você pode editar e finalizar novamente.</p>` : ''}</section></div>`}
function renderFlashcards() {const card = FLASHCARDS[cardIndex % FLASHCARDS.length], score = store.state.flashcards[card.id] || 0, reviewed = Object.keys(store.state.flashcards).length; return `${pageHead('REVISÃO ATIVA', 'Flashcards', 'Desafie sua memória: tente responder antes de virar o cartão.')}<div class="grid-3" style="margin-bottom:24px">${metric('layers', `${cardIndex + 1}/${FLASHCARDS.length}`, 'Cartão atual')}${metric('check', `${reviewed}/${FLASHCARDS.length}`, 'Cartões praticados')}${metric('refresh', String(score), 'Acertos registrados neste cartão')}</div><button type="button" class="flashcard ${flashRevealed ? 'is-revealed' : ''}" data-action="flip-card" aria-label="${flashRevealed ? 'Resposta do cartão. Virar para ver pergunta.' : 'Pergunta do cartão. Virar para ver resposta.'}"><span class="pill">${esc(AREAS[card.area].name)} · ${flashRevealed ? 'RESPOSTA' : 'PERGUNTA'}</span><span class="card-question">${esc(flashRevealed ? card.back : card.front)}</span><span class="card-hint">${icon('refresh')} Clique ou pressione Enter para virar</span></button><div class="flashcard-controls"><button type="button" class="button button-secondary" data-action="card-prev">${icon('arrowleft')} Anterior</button><button type="button" class="button button-secondary" data-action="flip-card">${icon('refresh')} Virar</button><button type="button" class="button button-primary" data-action="card-known">${icon('check')} Lembrei</button><button type="button" class="button button-secondary" data-action="card-next">Próximo ${icon('arrow')}</button></div><p class="small muted" style="text-align:center;margin-top:16px">Ao clicar em “Lembrei”, o cartão conta como revisado e você avança. Se ainda não souber, vire, estude e continue.</p>`}
function renderPerformance() {const attempts = store.state.quizAttempts; return `${pageHead('EVOLUÇÃO', 'Meu desempenho', 'Enxergue seus avanços e descubra o que merece mais atenção.')}<section class="grid-4">${metric('book', store.state.lessonDone.length, 'Capítulos concluídos', `de ${LESSONS.length} disponíveis`)}${metric('target', answeredCount(), 'Respostas registradas')}${metric('chart', `${totalAccuracy()}%`, 'Acertos em aulas')}${metric('flag', attempts.length, 'Treinos realizados')}</section><section class="grid-2 gap-section"><div class="card"><h2>Domínio por área</h2><p class="small">Percentual de acertos em exercícios de aulas, não nota ou previsão TRI.</p>${Object.entries(AREAS).map(([k, a]) => {const s = areaStats(k); return `<div class="chart-row"><span>${esc(a.short)}</span><div class="progress" role="progressbar" aria-label="${esc(a.name)}: ${s.accuracy}% de acertos" aria-valuenow="${s.accuracy}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s.accuracy}%"></span></div><span>${s.answered ? s.accuracy + '%' : '—'}</span></div>`}).join('')}<div class="note" style="margin-top:20px">Sem respostas, a barra fica vazia. Cada percentual considera apenas os exercícios respondidos.</div></div><div class="card"><h2>Biblioteca concluída</h2><p class="small">Acompanhe quantos capítulos você já finalizou em cada área.</p>${Object.entries(AREAS).map(([k, a]) => {const s = areaStats(k); return `<div class="chart-row"><span>${esc(a.short)}</span><div class="progress" role="progressbar" aria-label="${esc(a.name)}: ${s.finished} de ${s.total} capítulos concluídos" aria-valuenow="${percent(s.finished, s.total)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent(s.finished, s.total)}%"></span></div><span>${s.finished}/${s.total}</span></div>`}).join('')}<div class="divider"></div>${button('#/biblioteca', 'Continuar estudos', 'secondary', 'book')}</div></section><section class="card gap-section">${sectionHead('Suas prioridades', 'Comece pelas áreas com mais erros registrados')}${questionList().some(q => store.state.answers[q.key]) ? `<div class="grid-2">${Object.entries(AREAS).map(([k, a]) => {const s = areaStats(k); return {area: k, name: a.name, ...s}}).filter(s => s.answered > 0).sort((a, b) => a.accuracy - b.accuracy).slice(0, 2).map(s => `<div class="card tight"><span class="pill ${s.accuracy < 60 ? 'pill-rose' : 'pill-accent'}">${s.accuracy}% de acertos</span><h3 style="margin:12px 0 6px">${esc(s.name)}</h3><p class="small">${s.answered} questões respondidas</p><a href="#/biblioteca" class="text-link">Revisar conteúdos ${icon('arrow')}</a></div>`).join('')}</div>` : '<div class="empty-state">Faça exercícios nas aulas para receber recomendações de revisão.</div>'}</section>`}
function renderSettings() {const p = store.state.profile; return `${pageHead('PREFERÊNCIAS', 'Configurações', 'Ajuste o ambiente de estudo e cuide dos seus dados.')}<div class="grid-2"><section class="card settings-section"><div><h2>Aparência</h2><p class="small">O tema escuro já vem ativado. Sua escolha fica salva.</p></div><div class="radio-cards"><button type="button" class="radio-card ${store.state.theme === 'dark' ? 'active' : ''}" aria-pressed="${store.state.theme === 'dark'}" data-action="theme" data-theme="dark">${icon('moon')} Escuro</button><button type="button" class="radio-card ${store.state.theme === 'light' ? 'active' : ''}" aria-pressed="${store.state.theme === 'light'}" data-action="theme" data-theme="light">${icon('sun')} Claro</button></div><div class="divider" style="margin:3px 0"></div><h2>Perfil de estudos</h2><form id="profile-form" class="settings-section"><div class="field"><label for="profile-name">Como gostaria de ser chamada?</label><input id="profile-name" name="name" maxlength="48" required value="${esc(p.name)}"></div><div class="field"><label for="profile-course">Curso dos sonhos</label><input id="profile-course" name="course" maxlength="65" value="${esc(p.course)}"></div><div class="field"><label for="profile-goal">Meta diária de estudos (minutos)</label><input id="profile-goal" name="goal" type="number" min="15" max="360" step="15" value="${p.goalMinutes}" required></div><button class="button button-primary" type="submit">${icon('check')} Salvar preferências</button></form></section><div class="stack"><section class="card"><div class="spaced"><div class="profile-avatar" aria-hidden="true">${esc(firstName().charAt(0).toUpperCase())}</div><span class="pill ${store.user ? 'pill-mint' : 'pill-gold'}">${store.user ? 'Conta conectada' : 'Modo local'}</span></div><h2 style="margin:17px 0 5px">Minha conta</h2><p class="small">${store.user ? esc(store.user.email) : 'Faça login para sincronizar o conteúdo entre celular e computador.'}</p><p class="small">${store.syncStatus === 'error' ? `Sincronização com problema: ${esc(store.error)}` : store.user ? 'Seu progresso também é guardado localmente neste dispositivo.' : 'O modo local não sincroniza entre dispositivos.'}</p><button type="button" class="button button-secondary" data-action="account">${store.user ? 'Sair da conta' : 'Entrar ou criar conta'} ${icon('user')}</button></section><section class="card settings-section"><div><h2>Seus dados</h2><p class="small">Faça um backup em JSON ou importe um backup anterior. Importar substitui o progresso atual.</p></div><button type="button" class="button button-secondary" data-action="export">${icon('download')} Exportar meu progresso</button><label class="button button-secondary" for="import-file" style="cursor:pointer">${icon('upload')} Importar backup JSON</label><input id="import-file" type="file" accept="application/json,.json" class="sr-only"><div class="note warning"><strong>Importante:</strong> não compartilhe backups se contiverem redações ou informações pessoais.</div></section></div></div><section class="card gap-section"><h2>Materiais oficiais</h2><p class="small">Consulte documentos publicados pelo Inep. Nosso conteúdo é independente.</p><div class="footer-links"><a href="${OFFICIAL_LINKS.matrix}" target="_blank" rel="noopener noreferrer">Matriz de Referência ↗</a><a href="${OFFICIAL_LINKS.essay}" target="_blank" rel="noopener noreferrer">Cartilha da Redação 2026 ↗</a><a href="${OFFICIAL_LINKS.participant}" target="_blank" rel="noopener noreferrer">Página do Participante ↗</a></div></section>`}
let currentRoute = 'inicio', libraryFilter = 'all', librarySearch = '', essayTopic = ESSAY_TOPICS[0].id, cardIndex = 0, flashRevealed = false;
let quizSession = null, quizResult = null, skipRender = false, toastTimer = null, authMode = 'login', essaySaveTimer = null;
const routeNames = {inicio: 'Visão geral', biblioteca: 'Biblioteca', aula: 'Capítulo', plano: 'Meu plano', questoes: 'Questões e simulados', redacao: 'Redação', flashcards: 'Flashcards', desempenho: 'Meu desempenho', configuracoes: 'Configurações'};
function applyTheme() {document.documentElement.dataset.theme = store.state.theme; document.querySelector('meta[name="theme-color"]').content = store.state.theme === 'light' ? '#f5f6fb' : '#090c15'; try {localStorage.setItem('aurora-theme', store.state.theme)} catch {} }
function updateHeader() {applyTheme(); const label = store.user ? (store.state.profile.name || store.user.email) : 'Entrar'; $('#account-label').textContent = label; const status = $('#sync-state'); status.className = 'sync-state ' + (store.syncStatus === 'synced' ? 'synced' : store.syncStatus === 'error' ? 'error' : ''); $('#sync-label').textContent = ({synced: 'Sincronizado', syncing: 'Salvando…', local: 'Modo local', error: 'Erro de sync'})[store.syncStatus] || 'Modo local'; if (store.error) status.title = store.error;}
function render() {
  updateHeader(); const fragments = (location.hash.match(/^#\/([^/?]+)/) || []); const route = fragments[1] || 'inicio'; currentRoute = routeNames[route] ? route : 'inicio';
  $('#topbar-title').textContent = routeNames[currentRoute];
  document.querySelectorAll('[data-nav]').forEach(el => {const active = el.dataset.nav === currentRoute || currentRoute === 'aula' && el.dataset.nav === 'biblioteca'; el.classList.toggle('active', active); if (active) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current')});
  let content = '';
  switch (currentRoute) {
    case 'inicio': content = renderHome(); break;
    case 'biblioteca': content = renderLibrary(); break;
    case 'aula': {const id = location.hash.slice('#/aula/'.length).split(/[/?]/)[0], l = LESSONS.find(x => x.id === id); content = l ? renderLesson(l) : `${pageHead('ERRO', 'Capítulo não encontrado', 'Verifique o endereço e volte à biblioteca.')}${button('#/biblioteca', 'Ver biblioteca')}`; break}
    case 'plano': content = renderPlan(); break;
    case 'questoes': content = renderQuestions(); break;
    case 'redacao': content = renderEssay(); break;
    case 'flashcards': content = renderFlashcards(); break;
    case 'desempenho': content = renderPerformance(); break;
    case 'configuracoes': content = renderSettings(); break;
    default: content = renderHome();
  }
  main.innerHTML = content; hydrateIcons(main);
  if (currentRoute === 'biblioteca') filterLessons();
  if (currentRoute === 'questoes') updateQuizClock();
}
function announce(message) {$('#global-announcer').textContent = message}
function toast(message) {const t = $('#toast'); t.textContent = message; t.classList.add('visible'); if (toastTimer) clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove('visible'), 4200); announce(message)}
function closeMenu() {const sidebar = $('#sidebar'); sidebar.classList.remove('open'); $('#scrim').hidden = true; $('#menu-toggle').setAttribute('aria-expanded', 'false')}
function toggleMenu() {const sidebar = $('#sidebar'), open = !sidebar.classList.contains('open'); sidebar.classList.toggle('open', open); $('#scrim').hidden = !open; $('#menu-toggle').setAttribute('aria-expanded', String(open)); if (open) sidebar.querySelector('a')?.focus()}
function filterLessons() {const cards = main.querySelectorAll('[data-lesson-card]'); let visible = 0; cards.forEach(c => {const show = (libraryFilter === 'all' || c.dataset.area === libraryFilter) && c.dataset.search.includes(normalize(librarySearch)); c.hidden = !show; if (show) visible++}); const empty = $('#lesson-empty'); if (empty) empty.hidden = visible > 0}
function changeRoute() {if (essaySaveTimer) {clearTimeout(essaySaveTimer); essaySaveTimer = null; setDraft()} closeMenu(); quizResult = null; render(); window.scrollTo({top: 0, behavior: 'instant'}); main.focus({preventScroll: true})}
function friendlyAuthError(err) {const m = String(err?.message || 'Ocorreu um erro.'); if (/Invalid login credentials/i.test(m)) return 'E-mail ou senha incorretos.'; if (/Email not confirmed/i.test(m)) return 'Confirme seu e-mail antes de entrar. Veja também a caixa de spam.'; if (/User already registered/i.test(m)) return 'Este e-mail já está cadastrado. Tente entrar.'; if (/Password should be at least/i.test(m)) return 'A senha precisa ter pelo menos 6 caracteres.'; if (/rate limit/i.test(m)) return 'Muitas tentativas no momento. Tente novamente mais tarde.'; return m}
function setAuthMode(mode) {authMode = mode; const titles = {login: 'Bem-vinda de volta.', signup: 'Crie seu espaço.', reset: 'Recuperar acesso.', password: 'Escolha uma nova senha.'}; const texts = {login: 'Entre para manter seus estudos sincronizados em todos os dispositivos.', signup: 'Uma conta gratuita para levar seu progresso com você.', reset: 'Enviaremos um link de recuperação para o seu e-mail.', password: 'Digite uma senha nova para recuperar sua conta.'}; $('#auth-heading').textContent = titles[mode]; $('#auth-intro').textContent = texts[mode]; $('#auth-password').parentElement; const pw = $('#auth-password'); pw.closest('form'); pw.hidden = mode === 'reset'; pw.previousElementSibling.hidden = mode === 'reset'; pw.required = mode !== 'reset'; pw.autocomplete = mode === 'signup' || mode === 'password' ? 'new-password' : 'current-password'; $('#auth-email').parentElement; $('#auth-email').hidden = mode === 'password'; $('#auth-email').previousElementSibling.hidden = mode === 'password'; $('#auth-email').required = mode !== 'password'; $('#auth-submit').textContent = ({login: 'Entrar na minha conta', signup: 'Criar conta gratuita', reset: 'Enviar link de recuperação', password: 'Atualizar minha senha'})[mode]; $('#auth-switch').textContent = mode === 'signup' ? 'Já tenho conta' : 'Criar conta gratuita'; $('#auth-recovery').hidden = mode === 'reset' || mode === 'password'; $('#auth-switch').hidden = mode === 'password'; $('#auth-message').textContent = ''; $('#auth-message').className = 'auth-message'}
function openAuth(mode = 'login') {if (!store.configured || !store.client) {toast('Configure o Supabase em js/config.js para ativar o login. O site pode ser testado no modo local.'); return } setAuthMode(mode); $('#auth-dialog').showModal(); (mode === 'password' ? $('#auth-password') : $('#auth-email')).focus()}
function setAuthMessage(message, type = '') {const e = $('#auth-message'); e.textContent = message; e.className = 'auth-message ' + type}
async function submitAuth(e) {
  e.preventDefault(); const email = $('#auth-email').value.trim(), password = $('#auth-password').value, btn = $('#auth-submit'); btn.disabled = true; setAuthMessage('Processando sua solicitação…'); try {
    if (authMode === 'login') {await store.signIn(email, password); $('#auth-dialog').close(); toast('Você entrou. Seus estudos estão sendo sincronizados.')}
    else if (authMode === 'signup') {const res = await store.signUp(email, password); if (res.session) {$('#auth-dialog').close(); toast('Conta criada e conectada!')} else setAuthMessage('Conta criada! Verifique seu e-mail para confirmar o cadastro antes de entrar.', 'success')}
    else if (authMode === 'reset') {await store.resetPassword(email); setAuthMessage('Se o endereço estiver cadastrado, você receberá instruções por e-mail.', 'success')}
    else if (authMode === 'password') {await store.updatePassword(password); $('#auth-dialog').close(); store.authEvent = ''; toast('Senha atualizada. Você já pode continuar estudando.')}
  } catch (err) {setAuthMessage(friendlyAuthError(err), 'error')} finally {btn.disabled = false}
}
function updateQuizClock() {if (!quizSession || quizSession.mode !== 'timed') return; const left = Math.max(0, 1200 - Math.floor((Date.now() - quizSession.startedAt) / 1000)), el = $('#quiz-clock'); if (el) el.textContent = `${String(Math.floor(left / 60)).padStart(2, '0')}:${String(left % 60).padStart(2, '0')}`; if (left === 0) finishQuiz()}
function startQuiz(mode) {quizResult = null; const list = questionList().sort(() => Math.random() - .5).slice(0, mode === 'timed' ? 12 : 8); quizSession = {mode, list, index: 0, responses: {}, startedAt: Date.now()}; render(); window.scrollTo({top: 0})}
function finishQuiz() {if (!quizSession) return; const s = quizSession; let score = 0; const items = s.list.map((q, i) => {const chosen = s.responses[i] === undefined ? null : s.responses[i]; if (chosen === q.answer) score++; return {...q, chosen}}); quizResult = {mode: s.mode, total: s.list.length, score, elapsedSec: Math.floor((Date.now() - s.startedAt) / 1000), items, completedAt: new Date().toISOString()}; quizSession = null; store.update(st => {st.quizAttempts.push({mode: quizResult.mode, total: quizResult.total, score, completedAt: quizResult.completedAt}); st.quizAttempts = st.quizAttempts.slice(-60)}); window.scrollTo({top: 0}); toast('Treino finalizado. Confira a correção comentada.')}
function downloadBackup() {const data = store.exportProgress(), blob = new Blob([data], {type: 'application/json'}), url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = `say-backup-${isoToday()}.json`; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 2500); toast('Backup gerado. Guarde-o em um local privado.')}
function setDraft() {const text = $('#essay-editor')?.value; if (text === undefined) return; const id = essayTopic; skipRender = true; store.update(s => {s.essayDrafts[id] = text}); skipRender = false; $('#essay-word-count').textContent = text.trim() ? text.trim().split(/\s+/).length : 0; $('#essay-char-count').textContent = text.length; const status = $('#essay-status'); if (status) status.textContent = 'Rascunho salvo automaticamente'}

// Um único tratamento central de ações mantém a navegação e o HTML desacoplados.
document.addEventListener('click', async e => {
  const target = e.target.closest('[data-action]'); if (!target) return;
  const action = target.dataset.action, lessonId = target.dataset.lesson;
  try {
    switch (action) {
      case 'filter': libraryFilter = target.dataset.filter; main.querySelectorAll('[data-action=filter]').forEach(x => {x.classList.toggle('active', x.dataset.filter === libraryFilter); x.setAttribute('aria-pressed', String(x.dataset.filter === libraryFilter))}); filterLessons(); break;
      case 'check-plan': {const key = `${target.dataset.date}:${target.dataset.task}`; store.update(s => {s.planChecked[key] = !s.planChecked[key]}); break}
      case 'answer': {const key = `${lessonId}:${target.dataset.index}`, l = LESSONS.find(x => x.id === lessonId), q = l.questions[Number(target.dataset.index)], selected = Number(target.dataset.choice); if (store.state.answers[key]) return; store.update(s => {s.answers[key] = {selected, correct: selected === q.answer, at: Date.now()}}); break}
      case 'finish-lesson': store.update(s => {s.lessonDone = s.lessonDone.includes(lessonId) ? s.lessonDone.filter(id => id !== lessonId) : [...s.lessonDone, lessonId]}); toast(done(lessonId) ? 'Capítulo concluído! ✨' : 'Capítulo marcado como não concluído.'); break;
      case 'retry-lesson': store.update(s => {for (const k of Object.keys(s.answers)) if (k.startsWith(lessonId + ':')) delete s.answers[k]}); toast('Exercícios reiniciados.'); break;
      case 'start-quiz': startQuiz(target.dataset.mode); break;
      case 'leave-quiz': if (confirm('Encerrar este treino sem salvar o resultado?')) {quizSession = null; quizResult = null; render()} break;
      case 'quiz-answer': if (quizSession) {quizSession.responses[quizSession.index] = Number(target.dataset.choice); render()} break;
      case 'quiz-next': if (quizSession) {if (quizSession.responses[quizSession.index] === undefined) return; if (quizSession.index === quizSession.list.length - 1) finishQuiz(); else {quizSession.index++; render(); window.scrollTo({top: 0})} } break;
      case 'back-quiz': quizResult = null; render(); break;
      case 'flip-card': flashRevealed = !flashRevealed; render(); break;
      case 'card-prev': cardIndex = (cardIndex - 1 + FLASHCARDS.length) % FLASHCARDS.length; flashRevealed = false; render(); break;
      case 'card-next': cardIndex = (cardIndex + 1) % FLASHCARDS.length; flashRevealed = false; render(); break;
      case 'card-known': {const id = FLASHCARDS[cardIndex].id; store.update(s => {s.flashcards[id] = (Number(s.flashcards[id]) || 0) + 1}); cardIndex = (cardIndex + 1) % FLASHCARDS.length; flashRevealed = false; render(); break}
      case 'essay-check': break;
      case 'submit-essay': {const text = $('#essay-editor').value; if (!text.trim()) {toast('Escreva seu texto antes de finalizar.'); return } store.update(s => {s.essayDrafts[essayTopic] = text; s.essaySubmitted[essayTopic] = {text, savedAt: new Date().toISOString()}}); toast('Sua versão finalizada foi salva!'); break}
      case 'copy-essay': await navigator.clipboard.writeText($('#essay-editor').value); toast('Redação copiada para a área de transferência.'); break;
      case 'theme': store.update(s => {s.theme = target.dataset.theme}); break;
      case 'export': downloadBackup(); break;
      case 'account': if (store.user) {if (confirm('Deseja sair desta conta neste dispositivo?')) {await store.signOut(); toast('Você saiu da conta.')} } else openAuth(); break;
    }
  } catch (err) {toast(`Não foi possível concluir: ${err.message || 'erro inesperado'}`)}
});
document.addEventListener('input', e => {if (e.target.id === 'lesson-search') {librarySearch = e.target.value; filterLessons()} if (e.target.id === 'essay-editor') {if (essaySaveTimer) clearTimeout(essaySaveTimer); essaySaveTimer = setTimeout(setDraft, 350); $('#essay-word-count').textContent = e.target.value.trim() ? e.target.value.trim().split(/\s+/).length : 0; $('#essay-char-count').textContent = e.target.value.length} });
document.addEventListener('change', async e => {
  if (e.target.id === 'essay-topic') {if (essaySaveTimer) {clearTimeout(essaySaveTimer); setDraft()} essayTopic = e.target.value; render()}
  if (e.target.matches('[data-action=essay-check]')) {const i = e.target.dataset.check, id = essayTopic, checked = e.target.checked; store.update(s => {s.essayChecklist = s.essayChecklist || {}; s.essayChecklist[id] = s.essayChecklist[id] || {}; s.essayChecklist[id][i] = checked})}
  if (e.target.id === 'import-file') {const file = e.target.files?.[0]; if (!file) return; if (file.size > 2_000_000) {toast('O backup ultrapassa o limite de 2 MB.'); return } try {const content = await file.text(); if (!confirm('Importar substituirá todo o progresso atual. Deseja continuar?')) return; store.importProgress(content); toast('Backup importado com sucesso.')} catch (err) {toast(err.message)} finally {e.target.value = ''} }
});
document.addEventListener('submit', e => {if (e.target.id !== 'profile-form') return; e.preventDefault(); const form = new FormData(e.target), name = String(form.get('name') || '').trim(), course = String(form.get('course') || '').trim(), goal = Number(form.get('goal')); if (!name || goal < 15 || goal > 360 || !Number.isFinite(goal)) {toast('Informe nome e meta de 15 a 360 minutos.'); return } store.update(s => {s.profile = {name: name.slice(0, 48), course: course.slice(0, 65), goalMinutes: goal}}); toast('Preferências salvas!')});
window.addEventListener('hashchange', changeRoute);
$('#menu-toggle').addEventListener('click', toggleMenu); $('#mobile-more').addEventListener('click', toggleMenu); $('#scrim').addEventListener('click', closeMenu);
$('#account-button').addEventListener('click', () => {if (store.user) location.hash = '#/configuracoes'; else openAuth()});
$('#auth-form').addEventListener('submit', submitAuth);
$('#auth-switch').addEventListener('click', () => setAuthMode(authMode === 'signup' ? 'login' : 'signup'));
$('#auth-recovery').addEventListener('click', () => setAuthMode('reset'));
document.addEventListener('keydown', e => {if (e.key === 'Escape') closeMenu()});
setInterval(updateQuizClock, 1000);
store.onUpdate = () => {if (!skipRender) render(); else updateHeader(); if (store.authEvent === 'PASSWORD_RECOVERY') {store.authEvent = ''; openAuth('password')} };
hydrateIcons(document);
await store.init();
render();
if (!store.configured) {announce('Você está testando em modo local. Configure o Supabase para sincronizar entre aparelhos.')}
